import numpy as np


class Frame:
    """Interface for vector spaces generated by frames.

    A Frame stores a collection of R frame elements, each represented as a
    matrix of shape (N1, N2). The data is stored as a 3D array with shape
    (R, N1, N2), where:

    - R is the representation rank (number of basis elements)
    - N1 is the first physical dimension (output / row dimension)
    - N2 is the second physical dimension (input / column dimension)
    """

    def __init__(self, data: np.ndarray, is_orth: bool = False):
        if data.ndim != 3:
            raise ValueError(f"Get data with wrong number of dimensions, "
                             f"should be 3, got {data.ndim}")
        self._rank = data.shape[0]
        self._dim1 = data.shape[1]
        self._dim2 = data.shape[2]
        # immutable object: a writeable input is copied (the caller's array or
        # an alias of it could change the frame), a read-only one shared
        if data.flags.writeable:
            data = np.array(data, copy=True)
        self.data = data
        self.data.flags.writeable = False
        self._is_orth = is_orth

    # --- geometric properties ---
    @property
    def shape(self) -> tuple[int, int]:
        """Return the physical shape (dim1, dim2).

        Returns
        -------
        tuple of int
        """
        return (self._dim1, self._dim2)

    @property
    def dim(self) -> int:
        """Return the number of frame elements (representation rank).

        Returns
        -------
        int
        """
        return self._rank

    @property
    def is_orth(self):
        """Return whether the frame elements are orthonormal.

        Returns
        -------
        bool
        """
        return self._is_orth

    def storage(self) -> int:
        """Return the storage complexity of this frame.

        Returns
        -------
        int
            Total number of elements in the frame.
        """
        return self.data.size

    def sparse_storage(self) -> int:
        """Return the number of non-zero entries of this frame.

        Returns
        -------
        int
        """
        return int(np.count_nonzero(self.data))

    # --- fundamental tensorial algebra ---
    def matrix_times_space(self, mat) -> 'Frame':
        """Left multiply the physical dimension of each frame element.

        For each basis element, computes new_element = mat @ old_element.
        The output dimension dim1 is replaced by mat.shape[0].

        Parameters
        ----------
        mat : ndarray
            Matrix of shape (M, N1) where N1 must equal self.shape[0].

        Returns
        -------
        Frame
            New frame with shape (R, M, N2).
        """
        if mat.shape[1] != self.shape[0]:
            raise ValueError(f"Matrix shape {mat.shape} incompatible with "
                             f"dim1 of the Frame: {self.shape[0]}")
        # mat: (M, N1)
        # data: (R, N1, N2)
        # new_data: (R, M, N2)
        new_data = np.tensordot(mat, self.data,
                                axes=(1, 1)).swapaxes(0, 1)
        return self.__class__(new_data)

    def space_times_matrix(self, mat) -> 'Frame':
        """Apply a linear combination of the basis elements.

        Replace the frame by mat @ frame, where mat defines how to combine
        the original basis elements into new ones.

        Parameters
        ----------
        mat : ndarray
            Matrix of shape (K, R) where R must equal self.dim.

        Returns
        -------
        Frame
            New frame with shape (K, N1, N2).
        """
        if mat.shape[0] != self.dim:
            raise ValueError(f"Matrix shape {mat.shape[0]} is incompatible "
                             f"with the representation rank of the "
                             f"Frame: {self.dim}")
        # mat: (R, K)
        # data: (R, N1, N2)
        # new_data: (K, N1, N2)
        new_data = np.tensordot(mat, self.data, axes=(0, 0))
        return self.__class__(new_data)

    def dot(self, other: 'Frame') -> np.ndarray:
        """Compute the Gram matrix between self and other.

        Parameters
        ----------
        other : Frame
            Another frame with the same physical dimensions.

        Returns
        -------
        ndarray
            Gram matrix of shape (self.dim, other.dim).
        """
        if self.shape != other.shape:
            raise ValueError("Frames must have the same physical dimensions "
                             "to compute Gram matrix.")
        # self.data: (R, N1, N2)
        # other.data: (K, N1, N2)
        # gram: (R, K)
        gram = np.tensordot(self.data, other.data, axes=([1, 2], [1, 2]))
        return gram

    def orth(self) -> tuple['Frame', np.ndarray]:
        """Orthonormalize the frame and return the change-of-basis matrix.

        Parameters
        ----------
        None

        Returns
        -------
        Frame
            A new orthonormal frame.
        ndarray
            The R factor from the QR decomposition.
        """
        Q, R_fact = np.linalg.qr(self.data.reshape(self.dim, -1).T,
                                 mode="reduced")
        # if dim > N1 * N2, the reduced QR has only N1 * N2 columns: the
        # orthonormal frame has min(dim, N1 * N2) elements
        new_data = Q.T.reshape(Q.shape[1], self.shape[0], self.shape[1])
        return self.__class__(new_data, is_orth=True), R_fact

    def cat(self, other: "Frame") -> "Frame":
        """Concatenate the basis elements of two frames.

        The result represents the sum of the corresponding subspaces.
        Physical dimensions must match.

        Parameters
        ----------
        other : Frame
            Frame to concatenate with.

        Returns
        -------
        Frame
            New frame with rank = self.dim + other.dim.
        """
        if self.shape != other.shape:
            raise ValueError(
                "Physical dimensions must match for standard concatenation."
            )

        # concatenate the on the ranks axis
        new_data = np.concatenate((self.data, other.data), axis=0)
        return self.__class__(new_data, is_orth=False)

    def kron(self, other: 'Frame') -> 'Frame':
        """Kronecker product with another Frame.

        Parameters
        ----------
        other : Frame
            Frame to take the Kronecker product with.

        Returns
        -------
        Frame
            New frame with rank = self.dim * other.dim and physical
            dimensions multiplied component-wise.
        """
        r1, d1a, d1b = self.data.shape
        r2, d2a, d2b = other.data.shape
        new_data = np.zeros((r1 * r2, d1a * d2a, d1b * d2b))
        for i in range(r1):
            for j in range(r2):
                new_data[i * r2 + j] = np.kron(self.data[i], other.data[j])
        return self.__class__(new_data)

    def hadamard_product(self, other: 'Frame') -> 'Frame':
        """Entrywise (Hadamard) product of every pair of frame elements.

        The element i * other.dim + j of the result is self[i] * other[j],
        the same ordering as kron, so that the core of the Hadamard product of
        two Tucker tensors is the Kronecker product of their cores.

        Parameters
        ----------
        other : Frame
            Frame with the same physical dimensions.

        Returns
        -------
        Frame
            New frame with rank = self.dim * other.dim.
        """
        if self.shape != other.shape:
            raise ValueError("Frames must have the same physical dimensions "
                             "for the Hadamard product.")
        # (R1, 1, N1, N2) * (1, R2, N1, N2) -> (R1 * R2, N1, N2)
        new_data = self.data[:, None] * other.data[None, :]
        return self.__class__(new_data.reshape(-1, *self.shape))

    def super_frame(self, shape, rows=None, cols=None) -> 'Frame':
        """Embed the frame elements in larger matrices filled with zeros.

        The element k of the result is a matrix S_k of the given shape such
        that S_k[rows, cols] = self[k], and S_k is zero elsewhere.

        Parameters
        ----------
        shape : tuple of int
            Physical shape (M1, M2) of the new frame elements.
        rows : array-like of int, optional
            The N1 row indices of the current entries. The default is None,
            which keeps the rows unchanged (M1 must be N1).
        cols : array-like of int, optional
            The N2 column indices of the current entries. The default is None,
            which keeps the columns unchanged (M2 must be N2).

        Returns
        -------
        Frame
            New frame with shape (R, M1, M2).
        """
        index = []
        for axis, idx in enumerate((rows, cols)):
            if idx is None:
                if shape[axis] != self.shape[axis]:
                    raise ValueError(
                        f"Without indices, the size {shape[axis]} must be the "
                        f"current size {self.shape[axis]}.")
                idx = np.arange(self.shape[axis])
            idx = np.asarray(idx, dtype=int).ravel()
            if idx.size != self.shape[axis]:
                raise ValueError(
                    f"Got {idx.size} indices for a dimension of size "
                    f"{self.shape[axis]}.")
            index.append(idx)

        new_data = np.zeros((self.dim, *shape), dtype=self.data.dtype)
        new_data[:, index[0][:, None], index[1][None, :]] = self.data
        return self.__class__(new_data)

    def eval_in_space(self, coefs: np.ndarray) -> np.ndarray:
        """Evaluate a vector/operator from its coefficients in the frame.

        Computes y = sum_i c_i * space[i].

        Parameters
        ----------
        coefs : ndarray
            1D array of coefficients of length self.dim.

        Returns
        -------
        ndarray
            Array of shape (N1, N2).
        """
        if coefs.ndim != 1 or len(coefs) != self.dim:
            raise ValueError(f"Coefficients must be 1D array of size {self.dim}.")

        return np.tensordot(coefs, self.data, axes=(0, 0))


class FrameVector(Frame):
    """Specialization of Frame for vectors (states, functions).

    Enforces dim2 == 1, meaning each basis element is a column vector.
    Data shape: (R, N1, 1).
    """

    def __init__(self, data: np.ndarray, is_orth: bool = False):
        super().__init__(data, is_orth)
        if self.shape[1] != 1:
            raise ValueError(
                f"A FrameVector must have an input dimension (dim2) of 1, "
                f"but got {self.shape[1]}.")

    def eval_at_indices(self, dim1_idx) -> 'FrameVector':
        """Extract a sub-frame by selecting specific rows.

        Parameters
        ----------
        dim1_idx : array-like
            Indices along dim1 to keep.

        Returns
        -------
        FrameVector
            New frame with dim1 = len(dim1_idx).
        """
        # self.data: (R, N1, 1)
        # new_data: (R, N2, 1) with N2 = #dim1_idx
        new_data = self.data[:, dim1_idx, :]
        return self.__class__(new_data)

    def unvectorize(self, dim1: int, dim2: int, pattern=None) -> 'FrameOperator':
        """Reshape the vector frame into an operator frame.

        Parameters
        ----------
        dim1 : int
            First dimension of the resulting operator.
        dim2 : int
            Second dimension of the resulting operator.
            Must satisfy dim1 * dim2 == self.shape[0], or, with a pattern,
            dim1 * dim2 == number of entries of the matrices.
        pattern : numpy.ndarray, optional
            Sparsity pattern returned by FrameOperator.vectorize(pattern=True):
            the positions (in the C-order vectorization of the matrices) of
            the stored entries; the other entries are zero (Matlab: P of
            unvectorize).

        Returns
        -------
        FrameOperator
        """
        if pattern is not None:
            full = np.zeros((self.dim, dim1 * dim2, 1))
            full[:, np.asarray(pattern), :] = self.data
            return FrameVector(full).unvectorize(dim1, dim2)
        if dim1 * dim2 != self.shape[0]:
            raise ValueError(f"Cannot unvectorize dim1={self.shape[0]} into "
                             f"{dim1}x{dim2}.")

        # (R, N1, 1) --> (R, dim1, dim2)
        new_data = self.data.reshape(self.dim, dim1, dim2)

        return FrameOperator(new_data)

    def to_diagonal_operator(self) -> 'FrameOperator':
        """Convert the vector frame into a diagonal operator frame.

        Each basis vector v becomes a diagonal matrix diag(v).

        Returns
        -------
        FrameOperator
        """
        # (R, N1, 1) -> (R, N1, N1)
        new_data = np.zeros((self.dim, self.shape[0], self.shape[0]), dtype=self.data.dtype)
        idx = np.arange(self.shape[0])
        new_data[:, idx, idx] = self.data[:, :, 0]
        return FrameOperator(new_data)

    def dot_with_metric(
        self, other: "FrameVector", metric: "FrameOperator"
    ) -> np.ndarray:
        """Compute the inner product of basis vectors with a given metric.

        M[m, i, j] = self[i]^T * metric[m] * other[j]

        Parameters
        ----------
        other : FrameVector
        metric : FrameOperator
            Metric frame of shape (R3, N2, M2) where N2 must equal self.shape[0]
            and M2 must equal other.shape[0].

        Returns
        -------
        ndarray
            Array of shape (R3, self.dim, other.dim).
        """
        if metric.shape[0] != self.shape[0] or metric.shape[1] != other.shape[0]:
            raise ValueError("Incompatible physical dimensions for metric contraction.")

        # apply metrics to other
        # metric: (R3, N2, M2)
        # other: (R2, M2, 1)
        # tmp: (R3, N1, R2, 1)
        temp = np.tensordot(metric.data, other.data, axes=(2, 1))

        # compute the inner products
        # self_conj: (R1, N1, 1)
        # temp: (R3, N1, R2, 1)
        # res: (R1, R3, R2)
        res = np.tensordot(np.conj(self.data), temp, axes=([1, 2], [1, 3]))

        # target output shape: (R3, R1, R2)
        gram = res.swapaxes(0, 1)

        return gram

    def diag_cat(self, other: "FrameVector") -> "FrameVector":
        """Concatenate two frames in a block-diagonal fashion.

        The resulting frame has rank = self.dim + other.dim and
        dim1 = self.shape[0] + other.shape[0].

        Parameters
        ----------
        other : FrameVector

        Returns
        -------
        FrameVector
        """
        new_rank = self.dim + other.dim
        new_dim1 = self.shape[0] + other.shape[0]
        new_dim2 = 1

        new_data = np.zeros((new_rank, new_dim1, new_dim2), dtype=self.data.dtype)
        new_data[0:self.dim, 0:self.shape[0], 0] = self.data[:, :, 0]
        new_data[self.dim:, self.shape[0]:, 0] = other.data[:, :, 0]

        return self.__class__(new_data, is_orth=False)

    def elementwise_hadamard(self, other: "FrameVector") -> "FrameVector":
        """Compute the element-wise (Hadamard) product of two vector frames.

        Parameters
        ----------
        other : FrameVector
            Must have the same shape and rank as self.

        Returns
        -------
        FrameVector
        """
        if self.shape != other.shape or self.dim != other.dim:
            raise ValueError(
                "Frames must have the exact same shape for Hadamard product."
            )

        new_data = self.data * other.data
        return self.__class__(new_data, is_orth=False)


class FrameOperator(Frame):
    """Specialization of Frame for operators (matrices mapping N_in to N_out).

    Data shape: (R, N1, N2), where N1 is the output dimension and N2 is the
    input dimension.
    """

    def mtimes(self, other: 'Frame') -> 'Frame':
        """Compose this operator frame with another Frame.

        Equivalent to matrix multiplication: self @ other.
        When composed with a FrameVector, the result is a FrameVector;
        when composed with another FrameOperator, the result is a FrameOperator.

        Parameters
        ----------
        other : Frame or FrameVector or FrameOperator
            Must satisfy self.shape[1] == other.shape[0].

        Returns
        -------
        Frame
            Result of the composition.
        """
        if self.shape[1] != other.shape[0]:
            raise ValueError(f"Incompatible dimensions for composition: "
                             f"self.dim2={self.shape[1]} != other.dim1={other.shape[0]}")

        # self.data  : (R_a, N1, N2)
        # other.data : (R_b, M1, M2) with M1 = N2
        # new_data: (R_a, R_b, N1, M2)
        new_data = np.tensordot(self.data, other.data,
                                axes=(2, 1)).swapaxes(1, 2)

        new_rank = self.dim * other.dim
        # lexicographic ordering on (R_a, R_b) -> new_data (R_a.R_b, N1, M2)
        new_data = new_data.reshape(new_rank, self.shape[0], other.shape[1])
        return other.__class__(new_data)

    def transpose(self, conjugate: bool = False) -> 'FrameOperator':
        """Transpose (or conjugate transpose) the physical dimensions.

        Swaps dim1 and dim2 while keeping the rank axis intact.

        Parameters
        ----------
        conjugate : bool, optional
            If True, also take the complex conjugate. Default is False.

        Returns
        -------
        FrameOperator
        """
        # data: (R, N1, N2)
        # Keep the rank axis (0) intact, swap the physical axes (1 and 2)
        t_data = self.data.transpose(0, 2, 1)

        if conjugate:
            t_data = np.conj(t_data)

        return FrameOperator(t_data)

    @property
    def T(self) -> 'FrameOperator':
        """Syntactic sugar for transpose."""
        return self.transpose(conjugate=False)

    @property
    def H(self) -> 'FrameOperator':
        """Syntactic sugar for conjugate transpose (Hermitian)."""
        return self.transpose(conjugate=True)

    def vectorize(self, pattern: bool = False):
        """Flatten the operator into a column vector space.

        Reshapes from (R, N1, N2) to (R, N1 * N2, 1).

        Parameters
        ----------
        pattern : bool, optional
            If True, keep only the entries that are non-zero in at least one
            matrix of the frame (the union of the sparsity patterns), and also
            return their positions, for unvectorize (Matlab: vectorize with
            two outputs). The default is False.

        Returns
        -------
        FrameVector, or (FrameVector, numpy.ndarray) with pattern=True
        """
        new_dim = self.shape[0] * self.shape[1]
        new_data = self.data.reshape(self.dim, new_dim, 1)
        if pattern:
            positions = np.nonzero(np.any(new_data[:, :, 0] != 0, axis=0))[0]
            return FrameVector(new_data[:, positions, :]), positions

        return FrameVector(new_data, is_orth=self.is_orth)
